using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using McpServer;

var builder = Host.CreateApplicationBuilder(args);

// Redirect all logging to stderr so it doesn't corrupt the stdio JSON-RPC stream
builder.Logging.ClearProviders();
builder.Logging.AddConsole(opts => opts.LogToStandardErrorThreshold = LogLevel.Trace);

// Register HttpClient via DI
builder.Services.AddHttpClient("ExternalApi", client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

// Register MCP server with stdio transport, tools, and prompts
builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new() { Name = "my-mcp-server", Version = "1.0.0" };
    })
    .WithStdioServerTransport()
    .WithToolsFromAssembly()
    .WithPromptsFromAssembly();

await builder.Build().RunAsync();

